import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.RQXGjTIX.js";const p=JSON.parse('{"title":"常见问题与已知限制","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),o={name:"guide/faq.md"};function l(s,e,n,d,c,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="常见问题与已知限制" tabindex="-1">常见问题与已知限制 <a class="header-anchor" href="#常见问题与已知限制" aria-label="Permalink to &quot;常见问题与已知限制&quot;">​</a></h1><h2 id="为什么元件存气体却不显示压力" tabindex="-1">为什么元件存气体却不显示压力？ <a class="header-anchor" href="#为什么元件存气体却不显示压力" aria-label="Permalink to &quot;为什么元件存气体却不显示压力？&quot;">​</a></h2><p>因为元件只保存<strong>数量</strong>。压力是&quot;数量 ÷ 体积&quot;的推导量，而 ME 网络里没有&quot;体积&quot;这个概念。 真实的压力交接发生在 <a href="/appliedcraftedenergistics/guide/interface.html">ME 气体接口</a> 和 <a href="/appliedcraftedenergistics/guide/p2p.html">气体 P2P 隧道</a> 的缓冲罐里。</p><h2 id="_1-byte-到底是多少气体" tabindex="-1">1 byte 到底是多少气体？ <a class="header-anchor" href="#_1-byte-到底是多少气体" aria-label="Permalink to &quot;1 byte 到底是多少气体？&quot;">​</a></h2><p><strong>1 AE byte = 1,000 GU = 1,000 升 @ 100 kPa（1 atm）</strong>。 所以 1k 元件（1,024 字节）= 1,024,000 GU = 1,024 m³ 常压气体。</p><h2 id="装了升级卡后元件显示的容量为什么变大" tabindex="-1">装了升级卡后元件显示的容量为什么变大？ <a class="header-anchor" href="#装了升级卡后元件显示的容量为什么变大" aria-label="Permalink to &quot;装了升级卡后元件显示的容量为什么变大？&quot;">​</a></h2><p>升级卡提高的是<strong>该元件的字节上限</strong>。<code>1 byte = 1,000 GU</code> 的全局规则不变， 只是这只元件现在有更多字节可用。详见 <a href="/appliedcraftedenergistics/guide/upgrades.html">元件升级卡</a>。</p><h2 id="为什么-ccb-管道从-me-接口抽不到气" tabindex="-1">为什么 CCB 管道从 ME 接口抽不到气？ <a class="header-anchor" href="#为什么-ccb-管道从-me-接口抽不到气" aria-label="Permalink to &quot;为什么 CCB 管道从 ME 接口抽不到气？&quot;">​</a></h2><ul><li>检查 ME 接口里是否真的有气体（接口的存储槽 / 网络里的气体）；</li><li>检查管道压力是否<strong>严格高于</strong>接口侧压力；</li><li>检查接口是否被 AE2 的&quot;存储总线&quot;之类占用？ME 接口本身只被动提供气体能力， 它不会主动把气体推到相邻管道。</li></ul><h2 id="与-applied-pneumatics-pneumaticcraft-冲突吗" tabindex="-1">与 Applied Pneumatics / PneumaticCraft 冲突吗？ <a class="header-anchor" href="#与-applied-pneumatics-pneumaticcraft-冲突吗" aria-label="Permalink to &quot;与 Applied Pneumatics / PneumaticCraft 冲突吗？&quot;">​</a></h2><p>不冲突。已在同一 183 模组整合包中同时加载 <code>Applied Pneumatics 1.0.9</code>、<code>PneumaticCraft 8.2.24</code> 与本模组并启动验证；三者各自注册自己的 key type / 能力，互不覆盖。</p><h2 id="游戏崩溃了-报告里出现-gasbuffertank-1-或类似的-noclassdeffounderror" tabindex="-1">游戏崩溃了，报告里出现 <code>GasBufferTank$1</code> 或类似的 <code>NoClassDefFoundError</code> <a class="header-anchor" href="#游戏崩溃了-报告里出现-gasbuffertank-1-或类似的-noclassdeffounderror" aria-label="Permalink to &quot;游戏崩溃了，报告里出现 `GasBufferTank$1` 或类似的 `NoClassDefFoundError`&quot;">​</a></h2><p>先确认是不是<strong>在游戏运行中替换了 mod 的 jar</strong>。在运行中的实例里覆盖 jar，会让 JVM 打开的文件 与磁盘内容错位，随后任何一次懒加载都会失败（常见表现：玩一段时间后崩在某个方块实体上）。 处理方式：完全退出游戏 → 重新启动即可；同时以后替换 jar 前先关游戏。</p><p>如果重启后仍然复现，请带上 <code>crash-reports/</code> 与 <code>logs/latest.log</code> 到 <a href="https://github.com/DaKang233/AppliedCraftedEnergistics/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 反馈。</p><h2 id="已知限制-0-1-x" tabindex="-1">已知限制（0.1.x） <a class="header-anchor" href="#已知限制-0-1-x" aria-label="Permalink to &quot;已知限制（0.1.x）&quot;">​</a></h2><ul><li>便携式气体元件尚未实现；</li><li>ME 气体接口的&quot;气罐槽&quot;（把气体灌进 / 倒出 CCB 气罐物品）尚未实现；</li><li>不支持&quot;按气体族系过滤&quot;的分区（模糊卡对气体无意义）；</li><li>气体的配方以简化配方为主，不追求数值平衡。</li></ul><h2 id="反馈" tabindex="-1">反馈 <a class="header-anchor" href="#反馈" aria-label="Permalink to &quot;反馈&quot;">​</a></h2><ul><li>源码与问题追踪：<a href="https://github.com/DaKang233/AppliedCraftedEnergistics" target="_blank" rel="noreferrer">GitHub</a></li><li>下载：<a href="https://github.com/DaKang233/AppliedCraftedEnergistics/releases" target="_blank" rel="noreferrer">GitHub Releases</a></li></ul>',18)])])}const f=a(o,[["render",l]]);export{p as __pageData,f as default};
